import ipaddress
import socket
import sys

import pytest


def is_loopback(host):
    if isinstance(host, bytes):
        host = host.decode('ascii')
    if host == 'localhost':
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


def loopback_only(event, args):
    if event in ('socket.getaddrinfo', 'socket.gethostbyname', 'socket.gethostbyaddr'):
        if not is_loopback(args[0]):
            raise RuntimeError('Test attempted non-loopback DNS')
    elif event == 'socket.connect' and args[0].family in (socket.AF_INET, socket.AF_INET6):
        if not is_loopback(args[1][0]):
            raise RuntimeError('Test attempted a non-loopback connection')


sys.addaudithook(loopback_only)
raise SystemExit(pytest.main([
    'tests/test_requests.py', 'tests/test_lowlevel.py', 'tests/test_hooks.py',
    'tests/test_adapters.py', 'tests/test_testserver.py', '-q', '--tb=short',
    '--disable-warnings', '-k',
    'not connect_timeout and not total_timeout_connect and not test_errors and not proxy and not expired and not nosan',
]))
PY"

